func (da *ReconDestAgent) readOnlyDB(ctx context.Context) *gorm.DB {
	if da.IsNonPostgresSQL() {
		return da.replica.WithContext(ctx)
	}
	tx := da.replica.WithContext(ctx).Begin()
	tx.Exec("SET TRANSACTION READ ONLY")
	return tx
}

